mapper.select:
 SELECT
 DATE (create_time) as create_time,
 ROUND(sedentary_time,2) as sedentary_time,
 ROUND(sleep_time,2) as sleep_time,
 ROUND(heart_rate,2) as heart_rate,
 ROUND(body_temperature,2) as body_temperature
 FROM
smartwatch
 
     
         AND create_time > #{beginTime}
     
     
         AND create_time < #{endTime}
     
     
         AND equip_id = #{equipId}
     
 
 ORDER BY
 DATE(create_time);
